/** Preview saved one-time instructions; submit re-reads them authoritatively. */
export function useSavedPromptReview(input: {
  open: boolean;
  enabled: boolean;
  teamName: string;
  scheduleId?: string;
  reviewed: boolean;
}) {
  const { open, enabled, teamName, scheduleId, reviewed } = input;
  const [review, setReview] = useState<SavedPromptReview | null>(null);

  useEffect(() => setReview(null), [teamName, scheduleId, open]);
  useEffect(() => {
    if (!open || !enabled || !teamName) return;
    let cancelled = false;
    void api.teams.getSavedRequest(teamName).then((saved) => {
      if (cancelled) return;
      const prompt = saved?.prompt?.trim() ?? '';
      if (!prompt) {
        setReview(null);
        return;
      }
      setReview((current) =>
        current?.teamName === teamName && current.prompt === prompt
          ? current
          : { teamName, prompt, confirmed: reviewed }
      );
    }).catch(() => {
      // The submit path performs the authoritative read and reports errors.
    });
    return () => { cancelled = true; };
  }, [enabled, open, reviewed, teamName]);

  return [review, setReview] as const;
}

/** Saved instructions remain intact; acknowledgement authorizes only non-replay. */
export const HistoricalPromptReview = ({
  prompt, confirmed, onConfirmedChange,
}: HistoricalPromptReviewProps): React.JSX.Element => {
  const { t } = useAppTranslation('team');
  return (
    <section className="space-y-2 rounded-md border border-[var(--warning-border)] p-3">
      <p className="text-xs text-[var(--warning-text)]">
        {t('launch.schedule.historicalPromptReviewRequired')}
      </p>
      <pre className="max-h-32 overflow-auto whitespace-pre-wrap break-words rounded-md bg-[var(--color-surface-raised)] p-2 text-xs">
        {prompt}
      </pre>
      <div className="flex items-start gap-2">
        <Checkbox
          id="schedule-saved-prompt-reviewed"
          checked={confirmed}
          onCheckedChange={(value) => onConfirmedChange(value === true)}
        />
        <Label htmlFor="schedule-saved-prompt-reviewed" className="cursor-pointer text-xs font-normal">
          {t('launch.schedule.historicalPromptAcknowledged')}
        </Label>
      </div>
    </section>
  );
};
